const BUILD_ID='eV9Sw25JLbxibku09';
const BUILD_TAG='greenhouse-release-20260906f';
const COLUMNS=['upsertKey','stableId','company','title','location','departments','status','changeKind','firstPublished','sourceUpdatedAt','observedAt','applyUrl','coverageStatus','estimatedActorChargeUsd','runUrl'];
function preflight(c){
 const boards=String(c.companyBoards??'').split(/[\s,]+/).filter(Boolean).map(x=>x.toLowerCase()).sort();
 if(!boards.length||boards.length>3||boards.some(x=>! /^(eu:)?[a-z0-9][a-z0-9_-]{0,79}$/.test(x)||/replace/i.test(x))||new Set(boards).size!==boards.length)throw Error('Enter one to three distinct Greenhouse board slugs; prefix European boards with eu:.');
 const keywords=String(c.keywords??'').split(',').map(x=>x.trim()).filter(Boolean).sort();
 if(keywords.length>20||keywords.some(x=>x.length>100))throw Error('Use up to 20 comma-separated keywords.');
 if(typeof c.remoteOnly!=='boolean')throw Error('remoteOnly must be boolean.');
 if(!/^[A-Za-z0-9_-]{20,}$/.test(c.spreadsheetId??'')||/REPLACE/.test(c.spreadsheetId))throw Error('Set the spreadsheet ID before paid work.');
 if(!String(c.sheetName??'').trim()||! /^[\w.-]{1,64}$/.test(c.stateNamespace??''))throw Error('Set a Sheet tab and a stable watch name.');
 const cap=Number(c.maxCostPerRunUsd);if(!Number.isInteger(cap)||cap<1||cap>3)throw Error('Use an integer Actor charge cap from $1 to $3. Actual small runs usually cost less; unchanged jobs are billable.');
 const actorInput={workflow:'monitor',companyBoards:boards,jobTargets:[],keywords,department:String(c.department??'').trim(),location:String(c.location??'').trim(),remoteOnly:c.remoteOnly,firstPublishedAfter:'',includeContent:true,includeQuestions:false,includePayRanges:false,maxJobs:100,maxJobsPerBoard:1000,maxRuntimeSecs:60,maxBuyerChargeUsd:cap,stateNamespace:c.stateNamespace,firstRunBehavior:'emit_current_as_new'};
 const scope=JSON.stringify([actorInput.stateNamespace,boards,keywords,actorInput.department,actorInput.location,actorInput.remoteOnly,100,1000]);
 return {...c,boards,scope,actorInput,maxCostPerRunUsd:cap};
}
function classify(response,now=Date.now()){
 const run=response.data??response;
 if(!run.id||run.actId!==ACTOR_ID||run.buildId!==BUILD_ID)throw Error('Unexpected Actor or immutable build.');
 if(['FAILED','TIMED-OUT','ABORTED'].includes(run.status))throw Error('Actor '+run.status+'; inspect existing run '+run.id+'. No Sheet write.');
 if(!['READY','RUNNING','SUCCEEDED'].includes(run.status))throw Error('Unexpected Actor status.');
 if(run.status!=='SUCCEEDED'&&(!Number.isFinite(Date.parse(run.startedAt))||now-Date.parse(run.startedAt)>360000))throw Error('Polling deadline exceeded; inspect the existing run, never automatically repeat the paid call.');
 if(run.status==='SUCCEEDED'&&(!run.defaultDatasetId||!run.defaultKeyValueStoreId))throw Error('Missing run storage.');
 return {run,ready:run.status==='SUCCEEDED'};
}
function bounds(s){
 if(s.workflow!=='monitor'||s.coverageStatus!=='COMPLETE'||!Array.isArray(s.coverage)||!s.coverage.length||s.coverage.length>3||s.coverage.some(x=>!['COMPLETE','EMPTY_CONFIRMED'].includes(x.coverageStatus)))throw Error('Source coverage is incomplete; narrow filters before another paid run. Sheet unchanged.');
 for(const k of ['verifiedJobs','deliveredRecords','changes'])if(!Number.isInteger(s[k])||s[k]<0||s[k]>200)throw Error('Invalid output count.');
 if(s.verifiedJobs>100||s.deliveredRecords<s.verifiedJobs||s.changes<s.deliveredRecords-s.verifiedJobs)throw Error('Inconsistent output counts.');
 // Absences are both paid records and changes. Count them once in the dataset.
 const count=s.verifiedJobs+s.changes+s.coverage.length;
 if(count>303)throw Error('Unsupported dataset size.');
 return count;
}
function reconcile({config,run,summary,rows}){
 if(rows.length!==bounds(summary))throw Error('Dataset count differs from authoritative OUTPUT.');
 const expectedTargets=config.boards.map(x=>x.startsWith('eu:')?x:'us:'+x).sort();
 if(JSON.stringify(summary.coverage.map(x=>x.target).sort())!==JSON.stringify(expectedTargets))throw Error('Unexpected coverage targets.');
 const jobs=new Map(),changes=new Map();let coverage=0;
 for(const r of rows){
  if(r.recordType==='coverage'){coverage++;continue;}
  if(!/^greenhouse:(us|eu):[a-z0-9_-]+:\d+$/.test(r.stableId??'')||!expectedTargets.some(t=>r.stableId.startsWith('greenhouse:'+t+':')))throw Error('Invalid source identity.');
  const map=r.recordType==='job'?jobs:r.recordType==='change'?changes:null;
  if(!map||map.has(r.stableId))throw Error('Unexpected or duplicate source row.');
  if(map===changes&&!['NEW','UPDATED','CLOSED','LEFT_FILTER'].includes(r.changeKind))throw Error('Unexpected change type.');
  map.set(r.stableId,r);
 }
 if(jobs.size!==summary.verifiedJobs||changes.size!==summary.changes||coverage!==summary.coverage.length)throw Error('Dataset record counts do not reconcile.');
 const absent=[...changes.values()].filter(x=>['CLOSED','LEFT_FILTER'].includes(x.changeKind));
 if(jobs.size+absent.length!==summary.deliveredRecords||absent.some(x=>jobs.has(x.stableId)))throw Error('Absence conflicts with current jobs.');
 const prices=run.pricingInfo?.pricingPerEvent?.actorChargeEvents;
 const counts={search_checked:1,job_result:jobs.size,absence_result:absent.length};let charge=0;
 for(const [event,count]of Object.entries(counts)){const price=prices?.[event]?.eventPriceUsd;if(!Number.isFinite(price)||price<0)throw Error('Missing effective event price.');charge+=price*count;}
 if(!Number.isFinite(summary.expectedBuyerChargeUsd)||Math.abs(charge-summary.expectedBuyerChargeUsd)>1e-7||charge>config.maxCostPerRunUsd+1e-9)throw Error('Unreconciled estimated Actor charge.');
 for(const change of changes.values())if(['NEW','UPDATED'].includes(change.changeKind)&&!jobs.has(change.stableId))throw Error('Change is missing its current job.');
 return [...jobs.values(),...absent].map(r=>{const kind=changes.get(r.stableId)?.changeKind??'UNCHANGED';return {upsertKey:'greenhouse|'+config.scope+'|'+r.stableId,stableId:r.stableId,company:r.companyName??r.companyBoard,title:r.title??'',location:r.location??'',departments:(r.departments??[]).map(x=>x.name).join(', '),status:['CLOSED','LEFT_FILTER'].includes(kind)?kind:'OPEN',changeKind:kind,firstPublished:r.firstPublished??'',sourceUpdatedAt:r.updatedAt??'',observedAt:r.collectedAt,applyUrl:r.absoluteUrl??r.url??'',coverageStatus:'COMPLETE',estimatedActorChargeUsd:Number(charge.toFixed(9)),runUrl:'https://console.apify.com/actors/runs/'+run.id};});
}

return [{json:preflight($input.first().json)}];

